"""Tests for tools/check-dependency-locks.py (#1361).

They run the real uv on projects with no dependencies, so no network is used.
"""

from __future__ import annotations

import shutil
import subprocess
from pathlib import Path

import check_dependency_locks as locks
import pytest

pytestmark = pytest.mark.skipif(shutil.which("uv") is None, reason="requires uv")

HEADER = (
    "# This file was autogenerated by uv via the following command:\n"
    "#    uv pip compile docs/requirements.in --python-version 3.12 --generate-hashes "
    "--output-file docs/requirements.txt\n"
)


def _project(root: Path, name: str) -> Path:
    project = root / name
    project.mkdir(parents=True)
    (project / "pyproject.toml").write_text(
        f'[project]\nname = "{name.replace("/", "-")}"\nversion = "0"\n'
        'requires-python = ">=3.10"\ndependencies = []\n',
        encoding="utf-8",
    )
    subprocess.run(
        ["uv", "lock", "--offline", "--project", str(project)],
        check=True,
        capture_output=True,
        timeout=120,
    )
    return project


def _docs(root: Path) -> Path:
    (root / "docs").mkdir()
    (root / "docs/requirements.in").write_text("", encoding="utf-8")
    requirements = root / "docs/requirements.txt"
    requirements.write_text(HEADER, encoding="utf-8")
    subprocess.run(
        ["uv", *locks.docs_command(requirements)[1:]],
        cwd=root,
        check=True,
        capture_output=True,
        timeout=120,
    )
    return requirements


def _check(root: Path, projects: list[Path]) -> list[str]:
    version = locks.uv_version("uv")
    revision = locks.written_revision("uv")
    relative = [project.relative_to(root) for project in projects]
    return locks.check_uv_locks(
        root, relative, uv="uv", version=version, revision=revision
    ) + locks.check_docs_requirements(root, uv="uv", version=version)


def test_current_locks_pass_and_stay_unchanged(tmp_path: Path) -> None:
    project = _project(tmp_path, "app")
    requirements = _docs(tmp_path)
    before = ((project / "uv.lock").read_bytes(), requirements.read_bytes())

    assert _check(tmp_path, [project]) == []
    assert ((project / "uv.lock").read_bytes(), requirements.read_bytes()) == before


def test_a_lock_written_by_a_newer_uv_fails_and_names_the_command(tmp_path: Path) -> None:
    project = _project(tmp_path, "examples/app")
    _docs(tmp_path)
    lock = project / "uv.lock"
    revision = locks.written_revision("uv")
    newer = lock.read_text(encoding="utf-8").replace(
        f"revision = {revision}\n", f"revision = {revision + 2}\n"
    )
    lock.write_text(newer, encoding="utf-8")

    issues = _check(tmp_path, [project])

    assert len(issues) == 1
    assert f"lock revision {revision + 2}" in issues[0]
    assert "uv lock --project examples/app --upgrade-package" in issues[0]
    assert lock.read_text(encoding="utf-8") == newer


def test_a_lock_that_uv_rewrites_fails_and_is_restored(tmp_path: Path) -> None:
    project = _project(tmp_path, "app")
    _docs(tmp_path)
    lock = project / "uv.lock"
    edited = lock.read_text(encoding="utf-8").replace(
        'requires-python = ">=3.10"', 'requires-python = ">=3.11"', 1
    )
    assert edited != lock.read_text(encoding="utf-8")
    lock.write_text(edited, encoding="utf-8")

    issues = _check(tmp_path, [project])

    assert issues == [
        f"app/uv.lock differs from the output of: uv lock --project app "
        f"(uv {locks.uv_version('uv')}); run it and commit the result"
    ]
    assert lock.read_text(encoding="utf-8") == edited


def test_docs_requirements_that_differ_from_the_header_command_fail(tmp_path: Path) -> None:
    requirements = _docs(tmp_path)
    edited = requirements.read_text(encoding="utf-8") + "pip==26.3\n"
    requirements.write_text(edited, encoding="utf-8")

    issues = locks.check_docs_requirements(tmp_path, uv="uv", version="x")

    assert len(issues) == 1
    assert issues[0].startswith(
        "docs/requirements.txt differs from the output of its header command: "
        "uv pip compile docs/requirements.in --python-version 3.12"
    )
    assert requirements.read_text(encoding="utf-8") == edited


def test_docs_requirements_need_a_header_command(tmp_path: Path) -> None:
    (tmp_path / "docs").mkdir()
    (tmp_path / "docs/requirements.txt").write_text("ruff==0.17.4\n", encoding="utf-8")

    assert locks.check_docs_requirements(tmp_path, uv="uv", version="x") == [
        "docs/requirements.txt: the header names no `uv pip compile ... --output-file` command"
    ]


def test_the_repository_header_names_the_documented_command() -> None:
    command = locks.docs_command(locks.ROOT / locks.DOCS_REQUIREMENTS)

    assert command == [
        "uv",
        "pip",
        "compile",
        "docs/requirements.in",
        "--python-version",
        "3.12",
        "--generate-hashes",
        "--output-file",
        "docs/requirements.txt",
    ]
